/// <summary>
/// Extension code for buildComments
/// </summary>
/// <param name="_con">
/// Container containing the form state before controls are added.
/// </param>
/// <returns>
/// Container containing the form state after controls are added.
/// </returns>
container buildComments(container _con)
{
    container ret;

    ret = next buildComments(_con);

    ret = this.avaBuildComments(ret);

    return ret;
}

/// <summary>
/// Creates Comments form KCS_SOCSalesTableInfoFields
/// </summary>
/// <param name="_con">
/// Container containing the form state before controls are added.
/// </param>
/// <returns>
/// Container containing the form state after controls are added.
/// </returns>
public container avaBuildComments(container _con)
{
    container                   ret;
    KCS_SOCSalesTableInfoFields kcs_SOCSalesTableInfoFields;

    ret = _con;

    if (worktable
     && (worktable.WorkTransType == WHSWorkTransType::Sales || worktable.WorkTransType == WHSWorkTransType::TransferIssue)
     && worktable.OrderNum)
    {
        switch (worktable.WorkTransType)
        {
            case WHSWorkTransType::Sales:
                kcs_SOCSalesTableInfoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, worktable.OrderNum);
                break;
            case WHSWorkTransType::TransferIssue:
                kcs_SOCSalesTableInfoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::TransferOrderShip, worktable.OrderNum);
                break;
        }

        if (kcs_SOCSalesTableInfoFields
         && kcs_SOCSalesTableInfoFields.InfoField4)
        {
            ret += [this.buildControl(#RFLabel, #Comments, strFmt("@NDX:AVACommentsSalesOrder", kcs_SOCSalesTableInfoFields.SalesId, '\n', kcs_SOCSalesTableInfoFields.InfoField4), 1, '', #WHSRFUndefinedDataType, '', 0, true, "", WHSRFColorText::Default, extendedTypeNum(WHSShipmentId))];
        }
    }
    return ret;
}

/// <summary>
///Extension code for buildComments hasComments
/// </summary>
/// <returns>
/// True if the shipment has comments to be shown in RF.
/// </returns>
public boolean hasComments()
{
    boolean avaHasComments;

    avaHasComments = next hasComments();

    avaHasComments = avaHasComments || this.avaHasComments();

    return avaHasComments;
}

/// <summary>
/// Checks whether the shipment of the current work line has comments to be shown in RF.
/// </summary>
/// <returns>
/// True if the shipment has comments to be shown in RF.
/// </returns>
public boolean avaHasComments()
{
    boolean                     avaHasComments;
    KCS_SOCSalesTableInfoFields kcs_SOCSalesTableInfoFields;

    if (worktable
     && (worktable.WorkTransType == WHSWorkTransType::Sales || worktable.WorkTransType == WHSWorkTransType::TransferIssue)
     && worktable.OrderNum)

    {
        switch (worktable.WorkTransType)
        {
            case WHSWorkTransType::Sales:
                kcs_SOCSalesTableInfoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, worktable.OrderNum);
                break;
            case WHSWorkTransType::TransferIssue:
                kcs_SOCSalesTableInfoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::TransferOrderShip, worktable.OrderNum);
                break;
        }

        if (kcs_SOCSalesTableInfoFields
         && kcs_SOCSalesTableInfoFields.InfoField4)
        {
            avaHasComments = true;
        }
    }

    return avaHasComments;
}
